class Commune {
  final int id;
  final int wilayaCode;
  final String nameAr;
  final String nameFr;
  final String? parentCommuneAr;
  final String type; // "بلدية", "قرية", "دشرة", "تجمع سكاني", "واحة"
  final double latitude;
  final double longitude;

  const Commune({
    required this.id,
    required this.wilayaCode,
    required this.nameAr,
    required this.nameFr,
    this.parentCommuneAr,
    this.type = "بلدية",
    required this.latitude,
    required this.longitude,
  });

  String get displayName => parentCommuneAr != null
      ? "$nameAr ($type • بلدية $parentCommuneAr)"
      : "$nameAr ($type)";
}

