  static List<Commune> getCommunesByWilaya(int wilayaCode) {
    return allCommunes.where((c) => c.wilayaCode == wilayaCode).toList();
  }

  static Commune? getCommuneById(int id) {
    for (final c in allCommunes) {
      if (c.id == id) return c;
    }
    return null;
  }

  static List<Commune> searchCommunes(String query) {
    final q = query.trim().toLowerCase();
    if (q.isEmpty) return allCommunes;
    return allCommunes.where((c) {
      return c.nameAr.contains(q) ||
          c.nameFr.toLowerCase().contains(q) ||
          (c.parentCommuneAr != null && c.parentCommuneAr!.contains(q));
    }).toList();
  }

  static Commune findNearestCommune(double lat, double lng) {
    Commune nearest = allCommunes[0];
    double minDistance = double.infinity;

    for (final c in allCommunes) {
      final dLat = c.latitude - lat;
      final dLng = c.longitude - lng;
      final dist = (dLat * dLat) + (dLng * dLng);
      if (dist < minDistance) {
        minDistance = dist;
        nearest = c;
      }
    }
    return nearest;
  }
